const raw = String($json.data ?? $json.body ?? $json);
const events = [];
for (const frame of raw.split(/\n\n+/)) {
  const event = frame.match(/^event:\s*(.+)$/m)?.[1]?.trim();
  const data = frame.match(/^data:\s*(.+)$/m)?.[1]?.trim();
  if (!data) continue;
  try { events.push({ event, data: JSON.parse(data) }); } catch {}
}
const end = events.findLast((entry) => entry.event === 'end')?.data;
if (!end || end.status !== 'succeeded') throw new Error('OpenDesign/OpenCode did not complete successfully');
const artifactPath = end.artifactPaths?.find((path) => /\.html?$/i.test(path)) ?? 'index.html';
const projectId = $('Create OpenDesign project').first().json.project.id;
const webhook = $('Receive generation').first().json;
const input = webhook.body ?? webhook;
const productName = input.product_name ?? input.product?.product_name ?? $('Create OpenDesign project').first().json.project.name?.replace(/^Landing page\s+/i, '') ?? 'landing-page';
const jobId = input.job_id ?? projectId.replace(/^job-/, '');
const slug = productName.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
return [{ json: { job_id: jobId, project_id: projectId, artifact_path: artifactPath, slug } }];

const html = String($json.data ?? $json.body ?? $json).trim();
const source = $('Read generated artifact path').first().json;
if (!/<html[\s>]/i.test(html) || html.length > 500000) { return [{ json: { job_id: source.job_id, slug: source.slug, failed: true, error: 'OpenDesign artifact is not valid HTML' } }]; }
return [{ json: { job_id: source.job_id, slug: source.slug, failed: false, html } }];
